message.content:
{
  "css": "/* Identity surface content styles */

.product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: var(--title-gap);
}

.product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text-primary);
  word-break: keep-all;
  overflow-wrap: break-word;
}

.product-identity .price-row {
  margin-top: var(--price-gap);
}

.product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
}

.product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: var(--metadata-gap);
  margin-top: 24px;
}

.product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: var(--icon-label-gap);
}

.product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: var(--text-secondary);
}

.product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
}

.product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: var(--text-primary);
  margin-top: var(--content-gap);
  word-break: keep-all;
  overflow-wrap: break-word;
}"
}
